  1→"use client";
  2→
  3→/**
  4→ * Dashboard route (`/dashboard`).
  5→ *
  6→ * Orchestrates the multi-agent WebSocket hook, sidebar, chat panel, and
  7→ * task panel. Clicking "+" or selecting "New Agent" sets `activeAgentId`
  8→ * to `null`, which shows the spawn input. On spawn, the server responds
  9→ * with `spawned` and the hook auto-selects the new agent.
 10→ *
 11→ * ## Loading states
 12→ *
 13→ * Two loading flags from the hook control the UI:
 14→ * - `initialLoadDone` — false until the first `agent_list` arrives from
 15→ *   the server. While false, the sidebar shows skeleton rows.
 16→ * - `historyLoading` — true when the active agent's message history has
 17→ *   not been fetched yet (lazy loading). The chat shows a "Loading
 18→ *   messages..." indicator until the server responds.
 19→ *
 20→ * Sidebar uses `!initialLoadDone`, chat uses `!initialLoadDone || historyLoading`.
 21→ */
 22→
 23→import { useEffect, useState } from "react";
 24→import { useWebSocket } from "@/hooks/use-websocket";
 25→import { AgentSidebar } from "@/components/dashboard/agent-sidebar";
 26→import { Chat } from "@/components/dashboard/chat";
 27→import { TaskPanel, type TaskViewMode } from "@/components/dashboard/kanban-board";
 28→import { FolderBrowser } from "@/components/dashboard/folder-browser";
 29→import { cn } from "@/lib/utils";
 30→
 31→export default function DashboardPage() {
 32→  const {
 33→    connected,
 34→    initialLoadDone,
 35→    historyLoading,
 36→    agents,
 37→    agentOrder,
 38→    activeAgentId,
 39→    setActiveAgentId,
 40→    activeStatus,
 41→    activeMessages,
 42→    activeRawMessages,
 43→    spawnAgent,
 44→    sendMessage,
 45→    respondToControl,
 46→    respondToUserQuestion,
 47→    killAgent,
 48→    deleteAgent,
 49→    renameAgent,
 50→    clearHistory,
 51→    tasks,
 52→    createTask,
 53→    updateTask,
 54→    deleteTask,
 55→    delegateTask,
 56→    workspaces,
 57→    activeWorkspaceId,
 58→    setActiveWorkspaceId,
 59→    createWorkspace,
 60→    renameWorkspace,
 61→    deleteWorkspace,
 62→    browseDirectory,
 63→    directoryListing,
 64→  } = useWebSocket();
 65→
 66→  const [taskView, setTaskView] = useState<"hidden" | TaskViewMode>("hidden");
 67→  const [sidebarOpen, setSidebarOpen] = useState(false);
 68→  const [folderBrowserOpen, setFolderBrowserOpen] = useState(false);
 69→
 70→  // Derive initial path from first workspace or fallback to "/"
 71→  const initialBrowsePath = workspaces.length > 0 ? workspaces[0].cwd : "/";
 72→
 73→  useEffect(() => {
 74→    document.title = "thos — dashboard";
 75→  }, []);
 76→
 77→  return (
 78→    <div className="relative flex h-dvh overflow-hidden">
 79→      {/* Sidebar backdrop (mobile only) */}
 80→      {sidebarOpen && (
 81→        <div
 82→          className="fixed inset-0 z-40 bg-black/50 md:hidden"
 83→          onClick={() => setSidebarOpen(false)}
 84→        />
 85→      )}
 86→
 87→      {/* Sidebar drawer */}
 88→      <div
 89→        className={cn(
 90→          "fixed inset-y-0 left-0 z-50 w-56 transition-transform duration-200 ease-in-out md:relative md:z-auto md:translate-x-0 md:transition-none",
 91→          sidebarOpen ? "translate-x-0" : "-translate-x-full"
 92→        )}
 93→      >
 94→        <AgentSidebar
 95→          agents={agents}
 96→          agentOrder={agentOrder}
 97→          activeAgentId={activeAgentId}
 98→          loading={!initialLoadDone}
 99→          onSelect={(id) => {
100→            setActiveAgentId(id);
101→            setSidebarOpen(false);
102→          }}
103→          onNewAgent={() => {
104→            setActiveAgentId(null);
105→            setSidebarOpen(false);
106→          }}
107→          onKill={killAgent}
108→          onDelete={deleteAgent}
109→          onRename={renameAgent}
110→          onClearHistory={clearHistory}
111→          workspaces={workspaces}
112→          activeWorkspaceId={activeWorkspaceId}
