402→
403→function DraggableTaskCard({
404→  task,
405→  onUpdate,
406→  onDelete,
407→  onDelegate,
408→  onSelectAgent,
409→}: {
410→  task: Task;
411→  onUpdate: (taskId: string, updates: Partial<Pick<Task, "title" | "description" | "status" | "priority">>) => void;
412→  onDelete: (taskId: string) => void;
413→  onDelegate: (taskId: string) => void;
414→  onSelectAgent: (agentId: string) => void;
415→}) {
416→  const [dragging, setDragging] = useState(false);
417→
418→  return (
419→    <div
420→      draggable
421→      onDragStart={(e) => { e.dataTransfer.setData("text/plain", task.id); e.dataTransfer.effectAllowed = "move"; setDragging(true); }}
422→      onDragEnd={() => setDragging(false)}
